<?php $pageTitle='Add Patient';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/header.php';?><div class="card-panel"><form method="post" action="save.php"><h5 class="mb-3">Patient Information</h5><div class="row g-3"><div class="col-md-4"><label class="form-label">Patient ID *</label><input name="patient_code" class="form-control" placeholder="e.g. YAKAP-00001" maxlength="50" required></div><div class="col-md-4"><label class="form-label">PhilHealth ID *</label><input name="philhealth_id" class="form-control" required></div><div class="col-md-4"><label class="form-label">First Name *</label><input name="first_name" class="form-control" required></div><div class="col-md-4"><label class="form-label">Middle Name</label><input name="middle_name" class="form-control"></div><div class="col-md-4"><label class="form-label">Last Name *</label><input name="last_name" class="form-control" required></div><div class="col-md-4"><label class="form-label">Birthdate *</label><input type="date" name="birthdate" id="birthdate" class="form-control" required></div><div class="col-md-4"><label class="form-label">Age</label><input id="age" class="form-control" readonly placeholder="Auto computed"></div><div class="col-md-4"><label class="form-label">Sex *</label><select name="sex" class="form-select" required><option value="">Select Sex</option><option>Male</option><option>Female</option><option>Other</option></select></div><div class="col-md-8"><label class="form-label">Address</label><input name="address" class="form-control"></div><div class="col-md-4"><label class="form-label">Contact Number</label><input name="contact_number" class="form-control"></div></div><hr class="my-4"><button class="btn btn-primary">Save Patient</button> <a class="btn btn-secondary" href="index.php">Cancel</a></form></div><script>function calc(){let b=new Date(document.getElementById('birthdate').value),t=new Date(),a=t.getFullYear()-b.getFullYear(),m=t.getMonth()-b.getMonth();